use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary shell command string via `sh -c` and returns the output.
pub fn run_command(cmd: &str) -> Result<Output, io::Error> {
    Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()
}

/// Executes a command with explicit program + arguments and returns the output.
pub fn run_command_args(program: &str, args: &[&str]) -> Result<Output, io::Error> {
    Command::new(program)
        .args(args)
        .output()
}

/// Executes a shell command and returns stdout as a UTF-8 string.
pub fn run_command_output(cmd: &str) -> Result<String, Box<dyn std::error::Error>> {
    let output = run_command(cmd)?;
    let stdout = String::from_utf8(output.stdout)?;
    Ok(stdout)
}

